const accountFields = { Username: users.me.username, 'Display Name': users.me.name, Email: 'juniper@example.test', Phone: '7700900123' }
function profileEditor(local, account = {}) {
    const username = account.Username ?? users.me.username
    const server = local.tab === 1
    const field = server ? 'Server Nickname' : 'Display Name'
    const name = local[field] ?? account['Display Name'] ?? users.me.name
    const pronouns = local[server ? 'Server Pronouns' : 'Pronouns'] ?? account.Pronouns ?? users.me.pronouns
    const bioKey = server ? 'Server Bio' : 'Bio'
    const bio = local[bioKey] ?? account.Bio ?? users.me.bio
    const editField = (label, key, value) => `<label>${label}<span class="vp-profile-edit-input"><input aria-label="${label}" data-input="field:${key}" value="${esc(value)}"><button data-act="clearProfileField:${key}" aria-label="Clear ${label}">${icon('close',16)}</button></span></label>`
    const option = (label, value, glyph = 'disconnected') => `<label>${label}<button class="vp-profile-edit-option" data-act="detail:${label}">${icon(glyph,24)}<span>${value}</span>${icon('chevronRight',24)}</button></label>`
    return `${statusBar('MOBILE_ACTIONSHEET_BACKGROUND')}<div class="vp-page" data-k="bg:MOBILE_ACTIONSHEET_BACKGROUND">${pageHeader('Profile',{trailing:`<button class="vp-profile-save" data-act="save" data-k="fg:TEXT_BRAND" ${local.dirty ? '' : 'disabled'}>Save</button>`})}<nav class="vp-profile-edit-tabs">${['Main Profile','Per-server Profiles'].map((label,i)=>`<button data-act="tab:${i}" data-k="fg:${(local.tab ?? 0) === i ? 'TEXT_BRAND' : 'TEXT_MUTED'} bd:${(local.tab ?? 0) === i ? 'TEXT_BRAND' : 'BORDER_SUBTLE'}">${label}</button>`).join('')}</nav><div class="vp-page-scroll vp-profile-editor" data-scroll="profile-editor" data-fixed="Fictional profile colours and content">${server ? `<button class="vp-profile-server" data-act="detail:Choose Server" data-k="bg:CARD_MUTED_BG fg:TEXT_STRONG">${icon('chat',24)}<span>Maple Grove</span>${icon('chevronRight',24)}</button>` : ''}<div class="vp-profile-edit-banner"><div>${server ? '' : '<button data-go="profile:me">Preview profile</button>'}<button data-act="detail:Profile Banner" aria-label="Edit banner">${icon('pencil',20)}</button></div></div><div class="vp-profile-edit-identity"><button class="vp-profile-edit-avatar" data-act="detail:Profile Avatar" aria-label="Edit avatar">${avatar('me',80)}<i>${icon('pencil',16)}</i></button><button class="vp-profile-edit-status" data-act="detail:Add Status">${icon('plus',18)}Add Status</button><h2>${esc(name || username)}</h2><p>${esc(username)} &middot; ${esc(pronouns)}</p><span class="vp-profile-edit-badges" aria-label="Profile badges">${icon('nitro',22)} ${icon('games',22)} ${icon('boost',22)}</span></div><div class="vp-profile-edit-fields">${editField(server ? 'Server Nickname' : 'Display Name',field,name)}${option('Display Name Styles','None')}${editField('Pronouns',server ? 'Server Pronouns' : 'Pronouns',pronouns)}${server ? '<p>If left blank, your default pronouns will be used.</p>' : option('Badges',`${icon('nitro',22)} ${icon('games',22)} ${icon('boost',22)}`,'account')}<label>Bio<textarea aria-label="Bio" data-input="field:${bioKey}" maxlength="190">${esc(bio)}</textarea></label><label>Profile Theme<span class="vp-profile-edit-colours">${['Primary','Accent'].map(label=>`<button data-act="detail:Profile ${label} Colour" aria-label="${label} profile colour"><i>${icon('pencil',20)}</i>${label}</button>`).join('')}</span></label>${option('Avatar Decoration','None')}${option('Profile Effect','None')}</div></div></div>${navBar('MOBILE_ACTIONSHEET_BACKGROUND')}`
}
