        return `<div class="vp-scrim" data-close data-k="bg:BACKGROUND_SCRIM"></div><section class="vp-sheet vp-sensitive-sheet vp-typing-text-sheet" data-k="bg:MOBILE_ACTIONSHEET_BACKGROUND"><i class="vp-handle" data-k="bg:BACKGROUND_MOD_STRONG"></i><h2 data-k="fg:TEXT_STRONG">Text</h2>${radios('text',typingTextOptions,{text:typingTextOptions.indexOf(selected)})}</section><div class="vp-nav-scrim" data-k="bg:ANDROID_NAVIGATION_SCRIM_BACKGROUND"><i></i></div>`
