export const sensitiveFilterSheet = {
    id:'sensitive-filter', title:'Sensitive content filter', group:'Menus and sheets', capture:null,
    render({state}) {
        const {category=0,scope=0} = state?.overlayParams ?? {}
        const local = state?.ui?.['setting-detail']?.['Sensitive content filters'] ?? {}
        const options = scope === 2 ? ['Show','Blur'] : ['Show','Blur','Block']
        const selected = local[`${category}-${scope}`] ?? (scope === 1 ? 'Block' : 'Blur')
        return `<div class="vp-scrim" data-close data-k="bg:BACKGROUND_SCRIM"></div><section class="vp-sheet vp-sensitive-sheet" data-k="bg:MOBILE_ACTIONSHEET_BACKGROUND"><i class="vp-handle" data-k="bg:BACKGROUND_MOD_STRONG"></i><div><h2 data-k="fg:TEXT_STRONG">${sensitiveCategories[category][0]}</h2><p data-k="fg:TEXT_MUTED">${sensitiveScopes[scope]}</p></div>${radios('filter',options,{filter:options.indexOf(selected)})}</section><div class="vp-nav-scrim" data-k="bg:ANDROID_NAVIGATION_SCRIM_BACKGROUND"><i></i></div>`
    },
    actions:{select:({el,overlayParams,api})=>{
        const {category,scope}=overlayParams
        const options=scope === 2 ? ['Show','Blur'] : ['Show','Blur','Block']
        const local=((api.state.ui['setting-detail'] ??= {})['Sensitive content filters'] ??= {})
        local[`${category}-${scope}`]=options[Number(el.dataset.value)]
        api.close();api.render()
    }},
}
const detail = {
	id: 'setting-detail', title: 'Settings detail', group: 'Settings', capture: null,
	render({ params, ui, state }) {
		const name = params.id || 'Settings'
		const local = ui[name] ?? {}
        const savedUsername = state?.ui?.account?.Username ?? accountFields.Username
		let body
        if (name === 'Display Name') return profileEditor(local, state?.ui?.account)
        if (name === 'Enable Authenticator App') {
            const step = local.step ?? 0
            const header = `<header class="vp-page-header vp-auth-header" data-k="bb:BORDER_SUBTLE"><button class="vp-icon-btn" data-act="authBack" aria-label="${step ? 'Back' : 'Close'}" data-k="fg:INTERACTIVE_TEXT_DEFAULT">${icon(step ? 'back' : 'close',24)}</button><div class="vp-auth-progress" aria-label="${step < 2 ? `Step ${step + 1} of 2` : 'Enter authentication code'}"><i data-k="bg:${step === 0 ? 'TEXT_BRAND' : 'BACKGROUND_MOD_SUBTLE'} bd:BORDER_SUBTLE"></i><span data-k="bg:BORDER_SUBTLE"></span><i data-k="bg:${step === 1 ? 'TEXT_BRAND' : 'BACKGROUND_MOD_SUBTLE'} bd:BORDER_SUBTLE"></i></div></header>`
            const content = step === 0 ? `${settingsArt('google-authenticator','vp-auth-logo')}<h2 data-k="fg:TEXT_STRONG">Download an authenticator app</h2><p data-k="fg:TEXT_MUTED">Download and install <button data-act="authApp:Authy" data-k="fg:TEXT_LINK">Authy</button> or <button data-act="authApp:Google Authenticator" data-k="fg:TEXT_LINK">Google Authenticator</button> for your phone or tablet.</p>` : step === 1 ? `<h2 data-k="fg:TEXT_STRONG">Enter the 2FA Code</h2><p data-k="fg:TEXT_MUTED">Open your authentication app and enter the code below.<br><strong data-k="fg:TEXT_STRONG">demo key for preview only</strong><br><button data-act="authCopy" data-k="fg:TEXT_BRAND">Copy</button></p>` : `<h2 data-k="fg:TEXT_STRONG">Enter Discord Auth Code</h2><input class="vp-setting-input" inputmode="numeric" autocomplete="off" maxlength="6" aria-label="Discord Auth Code" data-input="field:authCode" data-enter="authVerify" value="${esc(local.authCode ?? '')}" data-k="bg:BACKGROUND_BASE_LOWEST fg:INPUT_TEXT_DEFAULT">`
            return `${statusBar('MOBILE_ACTIONSHEET_BACKGROUND')}<div class="vp-page vp-auth-page" data-k="bg:MOBILE_ACTIONSHEET_BACKGROUND">${header}<div class="vp-auth-content${step < 2 ? ' landing' : ''}${step === 1 ? ' setup-key' : step === 2 ? ' code-entry' : ''}">${content}</div>${step < 2 ? button('Next','authNext',true) : ''}</div>${navBar('MOBILE_ACTIONSHEET_BACKGROUND')}`
        }
        if (name === 'Security Keys and Passkeys' || name === 'Register a Security Key') {
            const register = name === 'Register a Security Key'
            const options = ['Create a passkey with your password manager', 'Create a passkey with your Android device', 'Enrol your Android device or an external key as a security key']
            return `${statusBar('BACKGROUND_BASE_LOW')}<div class="vp-page" data-k="bg:BACKGROUND_BASE_LOW">${pageHeader(name, {bg:'BACKGROUND_BASE_LOW', trailing:register ? '' : '<button data-act="detail:Register a Security Key" data-k="fg:TEXT_BRAND">Add</button>'})}<div class="vp-page-scroll vp-passkey-page${register ? ' vp-passkey-register' : ''}" data-scroll="setting-detail">${settingsArt(register ? 'passkey-register' : 'passkey-keychain', 'vp-passkey-illustration')}<p data-k="fg:${register ? 'TEXT_DEFAULT' : 'TEXT_MUTED'}">${register ? 'When you are ready to authenticate, press the button below.' : 'Secure your account by adding a Passkey or another supported security key.'}</p>${register ? `<div class="vp-passkey-options">${group(options.map((label,i)=>`<button class="vp-setting-control" role="radio" aria-checked="${(local.method ?? 0) === i}" data-act="select:method" data-value="${i}" data-k="fg:TEXT_STRONG bb:BORDER_SUBTLE"><span>${esc(label)}</span><span class="vp-radio" data-k="bd:${(local.method ?? 0) === i ? 'TEXT_STRONG' : 'INTERACTIVE_MUTED'}">${(local.method ?? 0) === i ? '<i data-k="bg:TEXT_BRAND"></i>' : ''}</span></button>`).join(''))}</div>${button('Let’s go','passkeyPreview',true)}` : ''}</div></div>${navBar('BACKGROUND_BASE_LOW')}`
        }
        if (name === 'Email') return `${statusBar('BACKGROUND_BASE_LOW')}<div class="vp-page" data-k="bg:BACKGROUND_BASE_LOWER">${pageHeader('', {close:true,bg:'BACKGROUND_BASE_LOW'})}<div class="vp-page-scroll vp-account-verify" data-scroll="setting-detail">${settingsArt('verify-email','vp-email-art')}<h2 data-k="fg:TEXT_STRONG">Verify Email</h2><p data-k="fg:TEXT_DEFAULT">We&#8217;ll need to verify your old email address, <b>juniper@example.test</b>, in order to change it.</p><p data-k="fg:TEXT_DEFAULT">Lost access to your email? Please contact your email provider to regain access.</p>${button('Send Verification Code','verifyEmail',true)}</div></div>${navBar('BACKGROUND_BASE_LOWER')}`
        if (name === 'Phone') return `${statusBar('BACKGROUND_BASE_LOW')}<div class="vp-page" data-k="bg:BACKGROUND_BASE_LOW">${pageHeader('',{close:true,bg:'BACKGROUND_BASE_LOW'})}<div class="vp-page-scroll vp-account-phone" data-scroll="setting-detail"><h2 data-k="fg:TEXT_STRONG">Update your phone number</h2>${sectionLabel('New Phone Number')}<div class="vp-phone-number" data-k="bg:BACKGROUND_BASE_LOWEST fg:TEXT_STRONG"><span>GB +44</span><input type="tel" aria-label="New Phone Number" data-input="field:Phone" value="${esc(local.Phone ?? accountFields.Phone)}"><button data-act="clearPhone" aria-label="Clear phone number" data-k="fg:TEXT_MUTED">${icon('close',20)}</button></div>${button('Next','phoneNext',true)}${button('Remove Phone Number','removePhone')}</div></div>${navBar('BACKGROUND_BASE_LOW')}`
        if (name === 'Username') body = `<div class="vp-account-username">${input(name,savedUsername,local)}<p data-k="fg:TEXT_DEFAULT">Please only use numbers, letters, underscores _ or full stops.</p></div>`
		else if (name in accountFields || name === 'Text') body = input(name, accountFields[name] ?? 'is typing...', local) + button('Save', 'save', true)
		else if (name === 'Password') body = `<div class="vp-account-password"><h2 data-k="fg:TEXT_STRONG">Update your password</h2><p data-k="fg:TEXT_DEFAULT">Please enter your existing password and your new password.</p>${['Current Password','New Password'].map(label=>`<label data-k="fg:TEXT_MUTED">${label} <span data-k="fg:TEXT_FEEDBACK_CRITICAL">*</span></label><input class="vp-setting-input" type="password" autocomplete="off" aria-label="${label}" data-input="field:${label}" value="${esc(local[label] ?? '')}" data-k="bg:INPUT_BACKGROUND_DEFAULT fg:INPUT_TEXT_DEFAULT bd:INPUT_BORDER_DEFAULT">`).join('')}${button('Change Password','changePassword',true).replace('class="','class="vp-password-submit ').replace('data-act=',`${!local['Current Password'] || !local['New Password'] ? 'disabled ' : ''}data-act=`)}</div>`
		else if (name === 'Input Mode') body = radios('mode', ['Voice Activity', 'Push-to-talk'], local)
		else if (name === 'Animation') body = radios('animation', ['None', 'Bounce', 'Wave'], local)
		else if (name === 'Sensitive content filters') body = `<div class="vp-sensitive-settings">${sensitiveCategories.map(([title,description],category)=>sectionLabel(title)+group(sensitiveScopes.map((label,scope)=>row(label,local[`${category}-${scope}`] ?? (scope === 1 ? 'Block' : 'Blur')).replace(`data-act="detail:${esc(label)}"`,`data-act="sensitiveFilter:${category}-${scope}"`)).join(''))+hint(description)).join('')}</div>`
		else if (name === 'Community Activity Alerts') body = servers.slice(1,6).map(server => sectionLabel(server.name) + group(toggle('In-app alerts', local, true, '', server.id + ' in-app') + toggle('Push notifications', local, true, '', server.id + ' push'))).join('')
		else if (name === 'Highlight Notifications') body = `<div class="vp-highlight-notifications" data-k="bg:CARD_MUTED_BG">${servers.map((server,index) => `<div class="vp-highlight-row">${serverIcon(server,40)}<div class="vp-highlight-control" data-k="bb:BORDER_SUBTLE"><span data-k="fg:TEXT_STRONG">${esc(server.name)}</span>${switchEl(local[server.id] ?? (index !== 0), `toggle:${server.id}`)}</div></div>`).join('')}</div>`
		else if (name === 'Add Connection') body = rowGroup(['Website', 'Facebook', 'GitHub', 'Spotify', 'Twitch', 'Xbox', 'YouTube'].map(label => ({ icon: 'globe', label, act: `provider:${label}` })))
		else if (['Lantern Music', 'Garden Dashboard', 'Orbit Games', 'Maple Calendar'].includes(name)) body = sectionLabel(name) + hint('This application can access your username and avatar.') + button(local.revoked ? 'Authorisation removed' : 'Deauthorise', 'revoke')
		else if (name === 'Request all of my data') body = `<div class="vp-data-request"><h2 data-k="fg:TEXT_STRONG">Submit Data Request</h2><p data-k="fg:TEXT_DEFAULT">Select the data you&#8217;d like to be included in your data package below. You can learn more about each of these selections <a href="https://support.discord.com/hc/en-us/articles/360004957991-Your-Discord-Data-Package" target="_blank" rel="noopener noreferrer" data-k="fg:TEXT_LINK">here</a>. Note that some selections, like Messages, may delay the delivery of your package and it may take us up to 30 days to collect your data. We will send you an email to the address you registered with when the package is ready.</p>${group(['Account','Your Activity','Activities','Ads','Messages','Servers','Support Tickets'].map(label=>`<button class="vp-setting-control" role="checkbox" aria-checked="${!!local[label]}" data-act="toggle:${label}" data-k="bg:CARD_MUTED_BG fg:TEXT_STRONG"><span>${label}</span><span class="vp-data-checkbox" data-k="bg:CHECKBOX_BACKGROUND_${local[label] ? 'SELECTED_DEFAULT' : 'DEFAULT'} bd:CHECKBOX_BORDER_${local[label] ? 'SELECTED_DEFAULT' : 'DEFAULT'} fg:CHECKBOX_ICON_ACTIVE">${local[label] ? icon('check',16) : ''}</span></button>`).join(''))}${button('Request My Data','request',true)}</div>`
		else if (name === 'Evaluate JavaScript') body = input('JavaScript', '1 + 1', local) + hint('Developer snippets are not executed by the website preview.')
		else if (name === 'Asset Browser') body = input('Search assets', '', local) + `<div class="vp-setting-tiles">${['apps', 'chat', 'bell', 'gear', 'gift', 'nitro'].map(glyph => `<div class="vp-card" data-asset="${glyph}" ${glyph.includes((local['Search assets'] ?? '').toLowerCase()) ? '' : 'hidden'} data-k="bg:CARD_MUTED_BG fg:TEXT_STRONG">${icon(glyph, 28)}<small>${glyph}</small></div>`).join('')}</div>`
		else if (name === 'Nitro Credit') body = sectionLabel('Nitro Credit') + hint('Unused subscription credit is applied when you start a matching Nitro subscription.') + hint('This preview has no available credit.')
		else if (name.includes('Gift')) body = sectionLabel('Choose a friend') + rowGroup(['Juniper', 'Rowan', 'Maple'].map(label => ({ icon: 'gift', label, act: `recipient:${label}` }))) + (local.recipient ? hint(`Gift selected for ${local.recipient}. No purchase has been made.`) : '')
		else if (name === 'Disable Account' || name === 'Delete Account') body = hint(`${name} ends access to this account. This studio uses fictional account information.`) + button(local.confirmed ? 'Preview confirmation complete' : 'Confirm', 'confirm')
		else body = hint(informational[name] || name) + (name === 'Scan QR Code' || name === 'Connect with Teen' ? `<div class="vp-setting-hero" data-k="bg:BACKGROUND_BASE_LOWEST fg:TEXT_MUTED">${icon('camera', 64)}</div>` : name === 'Upload debug logs to Discord Support' ? hint('Debug information can help diagnose app issues.') + button(local.prepared ? 'Logs prepared' : 'Prepare debug logs', 'prepare') : name.includes('notifications') ? group(toggle('Allow notifications', local, false)) : '')
		return `${statusBar('MOBILE_ACTIONSHEET_BACKGROUND')}<div class="vp-page" data-k="bg:MOBILE_ACTIONSHEET_BACKGROUND">${pageHeader(name,{trailing:name === 'Username' ? `<button class="vp-detail-save" data-act="save" data-k="fg:TEXT_BRAND" ${local.Username === undefined || local.Username === savedUsername ? 'hidden' : ''}>Save</button>` : ''})}<div class="vp-page-scroll" data-scroll="setting-detail">${body}</div></div>${navBar('MOBILE_ACTIONSHEET_BACKGROUND')}`
	},
	actions: Object.fromEntries(Object.entries({ ...actions,
        toggle: context => { const result = actions.toggle(context); if (['System notifications', 'Get notifications outside of Discord.'].includes(context.params.id)) (context.api.state.ui['notification-settings'] ??= {})[context.arg] = context.ui[context.arg]; return result },
        field: context => { actions.field(context); if (context.params.id === 'Display Name') { context.ui.dirty = true; const save = context.el.closest?.('.vp-page')?.querySelector('.vp-profile-save'); if (save) save.disabled = false; if (['Display Name','Server Nickname'].includes(context.arg)) { const heading = context.el.closest?.('.vp-page')?.querySelector('.vp-profile-edit-identity h2'); if (heading) heading.textContent = context.el.value || 'juniper_demo'; } } if (context.params.id === 'Password') { const submit = context.el.closest('.vp-page')?.querySelector('.vp-password-submit'); if (submit) submit.disabled = !context.ui['Current Password'] || !context.ui['New Password']; } if (context.params.id === 'Username') { const save = context.el.closest('.vp-page')?.querySelector('.vp-detail-save'); if (save) save.hidden = context.el.value === (context.api?.state?.ui?.account?.Username ?? accountFields.Username); } if (context.params.id === 'Asset Browser') for (const card of context.el.closest('.vp-page-scroll').querySelectorAll('[data-asset]')) card.hidden = !card.dataset.asset.includes(context.el.value.toLowerCase()) },
        select: context => { const result = actions.select(context); const { params, arg, ui, api } = context; if (params.id === 'Input Mode') (api.state.ui['voice-video'] ??= {}).mode = ui[arg]; if (params.id === 'Animation') (api.state.ui['typing-indicator'] ??= {}).animation = ui[arg]; return result },
        changePassword: ({ui,api}) => {delete ui['Current Password'];delete ui['New Password'];api.toast('default','Password change preview. No account was changed.');return 'render'},
        clearProfileField: ({arg,ui}) => { ui[arg] = ''; ui.dirty = true; return 'render' },
        sensitiveFilter: ({arg,api}) => {const [category,scope]=arg.split('-').map(Number);api.open('sensitive-filter',{category,scope,keepScreen:true})},
        authNext: ({ui}) => {ui.step = Math.min(2,(ui.step ?? 0)+1);return 'render'},
        authBack: ({ui,api}) => {if (ui.step) {ui.step--;return 'render'} ui.authCode='';api.back()},
        authApp: ({arg,api}) => api.toast('default',`${arg} download link preview.`),
        authCopy: async ({api}) => {try {await navigator.clipboard.writeText('demo key for preview only');api.toast('success','Demo key copied')} catch {api.toast('critical','Could not copy the demo key.')}},
        authVerify: ({ui,api}) => {api.toast('default',/^\d{6}$/.test(ui.authCode ?? '') ? 'Setup preview complete. No authenticator was enabled.' : 'Enter a six-digit demo code.');},
        passkeyPreview: ({api}) => api.toast('default','Passkey setup preview. No credential was created.'),
        verifyEmail: ({api}) => api.toast('default','Verification request preview. No email was sent.'),
        phoneNext: ({api}) => api.toast('default','Phone verification preview. No SMS was sent.'),
        clearPhone: ({ui}) => {ui.Phone='';return 'render'},
        removePhone: ({ui,api}) => {ui.Phone='';(api.state.ui.account ??= {}).Phone='Add a phone number';api.back()},
		save: ({ ui, params, api }) => { if (params.id === 'Display Name') { ui.dirty = false; for (const key of ['Pronouns','Bio']) if (ui[key] !== undefined) (api.state.ui.account ??= {})[key] = ui[key]; } if (params.id in accountFields && ui[params.id] !== undefined) (api.state.ui.account ??= {})[params.id] = ui[params.id]; if (params.id === 'Text') (api.state.ui['typing-indicator'] ??= {}).text = ui.Text; api.back() },
		provider: ({ arg, api }) => { (api.state.ui.connections ??= {})['removed-' + arg] = false; api.toast('success', `${arg} added to the local preview`); api.back() },
		revoke: ({ ui, params, api }) => { ui.revoked = true; (api.state.ui['authorised-apps'] ??= {})['revoked-' + params.id] = true; return 'render' }, add: ({ ui }) => { ui.added = true; return 'render' }, request: ({ api }) => api.toast('default','Data request preview. No request was sent.'),
		recipient: ({ arg, ui }) => { ui.recipient = arg; return 'render' }, confirm: ({ ui }) => { ui.confirmed = true; return 'render' }, prepare: ({ ui }) => { ui.prepared = true; return 'render' },
	}).map(([name, handler]) => [name, context => handler({ ...context, ui: (context.ui[context.params.id] ??= {}) })])),
}
settingsPages.push(detail)
